mapper.select:
/* SQL ID: com.winter.winter_back.domain.store.dao.findStoresWithDistance SQL 명: 매장 목록 조회 */ SELECT , ss.average_rating as averageRating, ss.total_reviews as reviewCount, ss.total_orders as orderCount, (6371 * acos(cos(radians(#{lat})) * cos(radians(s.latitude)) * cos(radians(s.longitude) - radians(#{lng})) + sin(radians(#{lat})) * sin(radians(s.latitude)))) AS distance, CASE WHEN s.status = 'OPEN' THEN true ELSE false END as isOpen FROM tb_store s LEFT JOIN tb_store_stats ss ON s.id = ss.store_id
AND s.category = #{category}
AND (6371 * acos(cos(radians(#{lat})) * cos(radians(s.latitude)) * cos(radians(s.longitude) - radians(#{lng})) + sin(radians(#{lat})) * sin(radians(s.latitude)))) <= #{maxDistance}
ORDER BY distance ASC
ORDER BY ss.average_rating DESC
ORDER BY ss.total_orders DESC
ORDER BY ss.total_reviews DESC
ORDER BY distance ASC
LIMIT #{size} OFFSET #{offset}

/*
SQL ID: com.winter.winter_back.domain.store.dao.countStoresWithDistance
SQL 명: 매장 목록 개수 조회
*/
SELECT COUNT(*)
FROM tb_store s


        AND s.category = #{category}


        AND (6371 * acos(cos(radians(#{lat})) * cos(radians(s.latitude))
        * cos(radians(s.longitude) - radians(#{lng}))
        + sin(radians(#{lat})) * sin(radians(s.latitude)))) <= #{maxDistance}

/* SQL ID: com.winter.winter_back.domain.store.dao.searchStoresWithDistance SQL 명: 매장 검색 */ SELECT , ss.average_rating as averageRating, ss.total_reviews as reviewCount,
(6371 * acos(cos(radians(#{lat})) * cos(radians(s.latitude)) * cos(radians(s.longitude) - radians(#{lng})) + sin(radians(#{lat})) * sin(radians(s.latitude)))) AS distance,
0 AS distance,
CASE WHEN s.status = 'OPEN' THEN true ELSE false END as isOpen FROM tb_store s LEFT JOIN tb_store_stats ss ON s.id = ss.store_id
ORDER BY distance ASC, s.id ASC LIMIT #{size} OFFSET #{offset}
